#!/usr/bin/env bash
# Prove `make-appcast.sh` signs the right feed and never leaks the key.
#
# **Fails today**: there is no such script, so an appcast would have been
# generated by hand -- which is how a private key ends up in a shell history,
# in argv, or in a file somebody forgets to delete.
#
# `generate_appcast` itself is Sparkle's and needs a real archive to read a
# bundle version out of, so it is stubbed here: the stub records its argv and
# its STDIN, which is exactly the surface this script decides.
set -euo pipefail

HERE="$(cd "$(dirname "$0")/.." && pwd)"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

SECRET='NOT-A-REAL-KEY-cS9cJ0nJt0hVh1V9Yb0nGZ0mQ1p2r3s4t5u6v7w8x9y='

mkdir -p "$WORK/bin" "$WORK/updates"
cat > "$WORK/bin/generate_appcast" <<'STUB'
#!/usr/bin/env bash
printf '%s\n' "$*" > "$OUT_DIR/argv"
cat > "$OUT_DIR/stdin"
# Whatever -o names, write a plausible signed feed there.
output=""
while [ "$#" -gt 0 ]; do
  if [ "$1" = "-o" ]; then output="$2"; fi
  shift
done
printf '<rss><item><enclosure sparkle:edSignature="abc" /></item></rss>\n' > "$output"
STUB
chmod +x "$WORK/bin/generate_appcast"
export OUT_DIR="$WORK"

run() {
  MOLD_NATIVE_SPARKLE_KEY="$SECRET" PATH="$WORK/bin:$PATH" \
    "$HERE/make-appcast.sh" --sparkle-bin-dir "$WORK/bin" "$@"
}

# Stable: the feed name the stable Info.plist URL ends in.
run --channel stable --updates-dir "$WORK/updates" --output "$WORK/out-stable.xml" \
  --download-url-prefix "https://github.com/utensils/mold/releases/download/v9.9.9/" > /dev/null
argv="$(cat "$WORK/argv")"

case "$argv" in
  *"--ed-key-file -"*) ;;
  *) echo "FAIL: the key was not read from stdin: $argv" >&2; exit 1 ;;
esac
# THE WHOLE POINT: the key is in stdin and NOWHERE else.
case "$argv" in
  *"$SECRET"*) echo "FAIL: the private key reached argv" >&2; exit 1 ;;
esac
if [ "$(cat "$WORK/stdin")" != "$SECRET" ]; then
  echo "FAIL: the key did not reach the tool's stdin" >&2
  exit 1
fi
case "$argv" in
  *"--download-url-prefix https://github.com/utensils/mold/releases/download/v9.9.9/"*) ;;
  *) echo "FAIL: the download prefix was not passed: $argv" >&2; exit 1 ;;
esac
# Two feeds, not Sparkle channels: --channel must never reach the tool, or the
# items get tagged and a stable updater ignores them.
case "$argv" in
  *--channel*) echo "FAIL: --channel was passed to generate_appcast: $argv" >&2; exit 1 ;;
esac

# Default output names, one per channel, matching the two feed URLs the app
# is pinned to.
run --channel nightly --updates-dir "$WORK/updates" > /dev/null
[ -s "$WORK/updates/mold-native-appcast-nightly.xml" ] \
  || { echo "FAIL: nightly default output name is wrong" >&2; exit 1; }
run --channel stable --updates-dir "$WORK/updates" > /dev/null
[ -s "$WORK/updates/mold-native-appcast.xml" ] \
  || { echo "FAIL: stable default output name is wrong" >&2; exit 1; }

refuses() {
  if run "$@" > /dev/null 2>&1; then return 1; fi
  return 0
}

# No key at all.
if MOLD_NATIVE_SPARKLE_KEY="" PATH="$WORK/bin:$PATH" \
  "$HERE/make-appcast.sh" --sparkle-bin-dir "$WORK/bin" --channel stable \
  --updates-dir "$WORK/updates" > /dev/null 2>&1; then
  echo "FAIL: an empty key must stop the run" >&2
  exit 1
fi

refuses --channel beta --updates-dir "$WORK/updates" \
  || { echo "FAIL: an unknown channel must be refused" >&2; exit 1; }
refuses --channel stable --updates-dir "$WORK/nowhere" \
  || { echo "FAIL: a missing updates directory must be refused" >&2; exit 1; }

# An UNSIGNED feed must stop the run, because that is what a silently
# key-less generate_appcast produces and Sparkle will install from none of it.
cat > "$WORK/bin/generate_appcast" <<'STUB'
#!/usr/bin/env bash
output=""
while [ "$#" -gt 0 ]; do
  if [ "$1" = "-o" ]; then output="$2"; fi
  shift
done
cat > /dev/null
printf '<rss><item><enclosure /></item></rss>\n' > "$output"
STUB
chmod +x "$WORK/bin/generate_appcast"
refuses --channel stable --updates-dir "$WORK/updates" --output "$WORK/unsigned.xml" \
  || { echo "FAIL: an unsigned appcast must stop the run" >&2; exit 1; }

echo "appcast recipe ok"
